public class StreamCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object call(byte[] data) {
        try {
            return StreamCounter.countBytes(new java.io.ByteArrayInputStream(data));
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("five bytes", 5,
                call("hello".getBytes(java.nio.charset.StandardCharsets.US_ASCII)));
        check("empty stream", 0, call(new byte[0]));
        check("single byte", 1, call(new byte[]{42}));
        check("1000 zero bytes", 1000, call(new byte[1000]));
        check("0xFF bytes are counted, not treated as end", 3,
                call(new byte[]{(byte) 0xFF, (byte) 0xFF, (byte) 0xFF}));
        check("mixed negative byte values", 4,
                call(new byte[]{-1, 0, 127, -128}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

